// ── Segundo widget: tarjeta de pasos (Recibido / Preparando / En camino / Entregado) ──

private let stepLabels = ["Recibido", "Preparando", "En camino", "Entregado"]
private let stepIconImages = [stepRecibidoImage, stepPreparandoImage, stepEnCaminoImage, stepEntregadoImage]

// Un restaurante del pedido (nombre + su logo, si se pudo descargar) — un
// pedido con carrito de varios restaurantes a la vez trae uno de estos por
// cada restaurante, no solo uno.
struct RestaurantLogoInfo {
  let name: String
  let logoData: Data?
}

struct GOGOTrackingStepsEntry: TimelineEntry {
  let date: Date
  let hasOrder: Bool
  let restaurantName: String
  let address: String
  let total: Double
  let stepIndex: Int
  let restaurants: [RestaurantLogoInfo]
  // Vacío hasta que el repartidor confirma el pedido (tracking_screen.dart
  // solo los manda una vez que _loadRepartidorProfile resuelve). Solo se
  // muestra la tarjeta blanca extra del repartidor en el tamaño grande del
  // widget (.systemLarge) cuando riderName no está vacío.
  let riderName: String
  let riderAvatarData: Data?
}

// Descarga el logo del restaurante con timeout corto — si falla o tarda, el
// widget se queda con el ícono de tienda genérico (mismo patrón que el
// timeout del mapa en renderMapSnapshot, para que un logo lento nunca
// trabe el widget).
private let logoFetchTimeout: TimeInterval = 3.0

private func fetchLogoImage(from url: URL, completion: @escaping (Data?) -> Void) {
  var didFinish = false
  let finishOnce: (Data?) -> Void = { data in
    if !didFinish { didFinish = true; completion(data) }
  }
  let task = URLSession.shared.dataTask(with: url) { data, _, error in
    guard error == nil, let data = data, UIImage(data: data) != nil else {
      finishOnce(nil)
      return
    }
    finishOnce(data)
  }
  DispatchQueue.main.asyncAfter(deadline: .now() + logoFetchTimeout) {
    task.cancel()
    finishOnce(nil)
  }
  task.resume()
}

// Descarga los logos de varios restaurantes en paralelo (mismo timeout de
// 3s cada uno, no acumulado) — para pedidos con carrito de varios
// restaurantes a la vez.
private func fetchRestaurantLogos(
  _ restaurants: [(name: String, urlString: String)],
  completion: @escaping ([RestaurantLogoInfo]) -> Void
) {
  if restaurants.isEmpty { completion([]); return }
  var results = [RestaurantLogoInfo?](repeating: nil, count: restaurants.count)
  let group = DispatchGroup()
  for (i, r) in restaurants.enumerated() {
    group.enter()
    guard !r.urlString.isEmpty, let url = URL(string: r.urlString) else {
      results[i] = RestaurantLogoInfo(name: r.name, logoData: nil)
      group.leave()
      continue
    }
    fetchLogoImage(from: url) { data in
      results[i] = RestaurantLogoInfo(name: r.name, logoData: data)
      group.leave()
    }
  }
  group.notify(queue: .main) {
    completion(results.compactMap { $0 })
  }
}

// Decodifica el JSON guardado por tracking_screen.dart (lista de
// {"name": ..., "imageUrl": ...}) en pares nombre/url — sin Codable, es un
// formato simple y no vale la pena el modelo extra.
private func parseRestaurantsJson(_ json: String) -> [(name: String, urlString: String)] {
  guard let data = json.data(using: .utf8),
        let array = try? JSONSerialization.jsonObject(with: data) as? [[String: String]]
  else { return [] }
  return array.map { (name: $0["name"] ?? "", urlString: $0["imageUrl"] ?? "") }
}

struct GOGOTrackingStepsProvider: TimelineProvider {
  func placeholder(in context: Context) -> GOGOTrackingStepsEntry {
    GOGOTrackingStepsEntry(date: Date(), hasOrder: true, restaurantName: "McDonalds",
                            address: "Clara Cordoba Moran #16", total: 35, stepIndex: 1,
                            restaurants: [RestaurantLogoInfo(name: "McDonalds", logoData: nil)],
                            riderName: "Roberto Garcia", riderAvatarData: nil)
  }

  func getSnapshot(in context: Context, completion: @escaping (GOGOTrackingStepsEntry) -> Void) {
    buildEntry(completion: completion)
  }

  func getTimeline(in context: Context, completion: @escaping (Timeline<GOGOTrackingStepsEntry>) -> Void) {
    refreshOrderFromSupabase { _ in
      buildEntry { entry in
        let policy: TimelineReloadPolicy = entry.hasOrder
          ? .after(Date().addingTimeInterval(widgetReloadInterval))
          : .never
        completion(Timeline(entries: [entry], policy: policy))
      }
    }
  }

  private func buildEntry(completion: @escaping (GOGOTrackingStepsEntry) -> Void) {
    let data = UserDefaults(suiteName: appGroupId)
    let hasOrder = data?.bool(forKey: "hasActiveOrder") ?? false
    let restaurantName = data?.string(forKey: "restaurantName") ?? ""
    let address = data?.string(forKey: "address") ?? ""
    let total = data?.object(forKey: "total") as? Double ?? 0
    let stepIndex = data?.object(forKey: "stepIndex") as? Int ?? 0
    let restaurantsJson = data?.string(forKey: "restaurantsJson") ?? ""
    // Compatibilidad hacia atrás: si todavía no hay restaurantsJson guardado
    // (widget viejo/pedido guardado antes de este cambio), cae al único
    // restaurantImageUrl de siempre.
    let legacyLogoUrlString = data?.string(forKey: "restaurantImageUrl") ?? ""
    let riderName = data?.string(forKey: "riderName") ?? ""
    let riderAvatarUrlString = data?.string(forKey: "riderAvatarUrl") ?? ""

    func makeEntry(_ restaurants: [RestaurantLogoInfo], _ riderAvatarData: Data?) -> GOGOTrackingStepsEntry {
      GOGOTrackingStepsEntry(date: Date(), hasOrder: hasOrder, restaurantName: restaurantName,
                             address: address, total: total, stepIndex: stepIndex,
                             restaurants: restaurants, riderName: riderName,
                             riderAvatarData: riderAvatarData)
    }

    let parsed = parseRestaurantsJson(restaurantsJson)
    let restaurantsToFetch = !parsed.isEmpty
      ? parsed
      : [(name: restaurantName, urlString: legacyLogoUrlString)]

    fetchRestaurantLogos(restaurantsToFetch) { restaurants in
      guard !riderAvatarUrlString.isEmpty, let url = URL(string: riderAvatarUrlString) else {
        completion(makeEntry(restaurants, nil))
        return
      }
      fetchLogoImage(from: url) { riderAvatarData in
        completion(makeEntry(restaurants, riderAvatarData))
      }
    }
  }
}

struct GOGOTrackingStepsWidgetEntryView: View {
  var entry: GOGOTrackingStepsProvider.Entry
  private let orange = Color(red: 244 / 255, green: 81 / 255, blue: 12 / 255)

  // Un logo si el pedido es de un solo restaurante (igual que siempre);
  // varios logos en fila, uno por restaurante, si el carrito tenía más de
  // uno a la vez.
