  private var restaurantLogosView: some View {
    if entry.restaurants.count > 1 {
      HStack(spacing: -10) {
        ForEach(Array(entry.restaurants.prefix(4).enumerated()), id: \.offset) { _, r in
          ZStack {
            Circle().fill(Color.white.opacity(0.18))
            if let data = r.logoData, let uiImage = UIImage(data: data) {
              Image(uiImage: uiImage)
                .resizable()
                .aspectRatio(contentMode: .fill)
                .frame(width: 32, height: 32)
                .clipShape(Circle())
            } else {
              Image(systemName: "storefront.fill").foregroundColor(.white).font(.caption)
            }
          }
          .frame(width: 32, height: 32)
          .overlay(Circle().stroke(orange, lineWidth: 2))
        }
      }
    } else {
      ZStack {
        Circle().fill(Color.white.opacity(0.75))
        if let data = entry.restaurants.first?.logoData, let uiImage = UIImage(data: data) {
          Image(uiImage: uiImage)
            .resizable()
            .aspectRatio(contentMode: .fill)
            .frame(width: 40, height: 40)
            .clipShape(Circle())
        } else {
          Image(systemName: "storefront.fill").foregroundColor(orange).font(.title3)
        }
      }
      .frame(width: 40, height: 40)
    }
  }

  // Wordmark GOGOFOOD arriba a la izquierda (sin la franja blanca decorativa
  // de antes, y ya no centrado).
