    HStack {
      if let watermark = gogoWatermarkImage {
        Image(uiImage: watermark)
          .resizable()
          .aspectRatio(contentMode: .fit)
          .frame(height: 10)
      }
      Spacer()
    }
    .padding(.top, 8)
    .padding(.leading, 12)
  }

  @Environment(\.widgetFamily) private var family

  // Tarjeta blanca extra con el repartidor confirmado (nombre + botón de
  // chat) — solo cabe en el tamaño grande (.systemLarge); en mediano no hay
  // espacio y se sigue viendo exactamente igual que antes.
