                .font(.headline)
                .foregroundColor(.white)
                .lineLimit(1)
              HStack(spacing: 3) {
                if let pin = pinIconImage {
                  Image(uiImage: pin)
                    .resizable()
                    .aspectRatio(contentMode: .fit)
                    .frame(width: 8, height: 11)
                } else {
                  Image(systemName: "mappin.and.ellipse")
                    .font(.system(size: 9))
                    .foregroundColor(.white.opacity(0.7))
                }
                Text(entry.address)
                  .font(.caption2)
                  .foregroundColor(.white.opacity(0.7))
                  .lineLimit(1)
              }
            }
            Spacer()
            VStack(alignment: .trailing, spacing: 0) {
              Text("$\(Int(entry.total))")
                .font(.system(size: 24, weight: .heavy))
                .foregroundColor(.white)
              Text("MXN")
                .font(.system(size: 9, weight: .bold))
                .foregroundColor(.white.opacity(0.85))
            }
          }

          // Línea de progreso pasando a la altura del centro de las
          // bolitas (13pt = mitad de su alto de 26pt), en vez de una barra
          // aparte arriba — así se ve como un solo riel conectando los 4 pasos.
          ZStack(alignment: .top) {
            GeometryReader { geo in
              ZStack(alignment: .leading) {
                Capsule().fill(Color.white).frame(height: 3)
                Capsule().fill(Color.blue)
                  .frame(width: geo.size.width * CGFloat(entry.stepIndex) / 3.0, height: 3)
              }
            }
            .padding(.horizontal, 13)
            .frame(height: 3)
            .padding(.top, 13)

            HStack {
              ForEach(0..<4, id: \.self) { i in
                VStack(spacing: 4) {
                  ZStack {
                    // Sin confirmar todavía: bolita blanca, ícono naranja.
                    // Ya confirmado (el paso actual o uno anterior): bolita
                    // azul, ícono blanco.
                    Circle()
                      .fill(i <= entry.stepIndex ? Color.blue : Color.white)
                      .overlay(Circle().stroke(Color.white, lineWidth: 2))
                    Group {
                      if let img = stepIconImages[i] {
                        Image(uiImage: img)
                          .renderingMode(.template)
                          .resizable()
                          .scaledToFit()
                          .frame(width: 13, height: 13)
                      } else {
                        Image(systemName: "circle")
                          .font(.system(size: 11))
                      }
                    }
                    .foregroundColor(i <= entry.stepIndex ? .white : orange)
                  }
                  .frame(width: 26, height: 26)
                  Text(stepLabels[i].uppercased())
                    .font(.system(size: 7, weight: .bold))
                    .foregroundColor(.white)
                    .lineLimit(1)
                }
                if i < 3 { Spacer() }
              }
            }
          }

          // El texto de "Rastrea tu pedido" y el botón "Cancelar pedido"
          // solo caben en el tamaño grande (.systemLarge) — en mediano el
          // alto fijo que da iOS no alcanza ni para esto ni para el header
          // completo; medirlo en el widget real (no en la vista previa de
          // Xcode) mostró que se cortaban, así que en mediano se quedan
          // fuera y solo se ve header + restaurante + los 4 pasos.
          if family == .systemLarge {
            Text("Rastrea Tu Pedido en Tiempo Real")
              .font(.system(size: 9, weight: .bold))
              .foregroundColor(Color(red: 12 / 255, green: 182 / 255, blue: 244 / 255))
              .frame(maxWidth: .infinity, alignment: .center)

            // El widget no puede cancelar el pedido por sí mismo (WidgetKit
            // sin App Intents no corre networking en respuesta a un tap),
            // así que solo abre la app como el resto de la tarjeta; ahí el
            // cliente ya puede cancelar.
            Text("Cancelar pedido")
              .font(.system(size: 13, weight: .bold))
              .foregroundColor(.white)
              .frame(maxWidth: .infinity)
              .padding(.vertical, 8)
              .background(
                ZStack {
                  Capsule().fill(Color(red: 122 / 255, green: 28 / 255, blue: 8 / 255))
                  Capsule().fill(
                    LinearGradient(colors: [Color.white.opacity(0.16), Color.clear],
                                   startPoint: .top, endPoint: .center)
                  )
                }
              )
          }
        }
        .padding(.horizontal, 12)
        .padding(.bottom, 14)
        .padding(.top, 28)
      } else {
        EmptyOrderView()
      }
    }
    }
  }

  // .systemSmall — el "piso" mínimo para quien prefiera el widget lo más
  // chico posible: solo el círculo del paso actual (mismo estilo que ya
  // usan los 4 pasos en mediano/grande) + su etiqueta y el restaurante.
  private var smallBody: some View {
    Group {
      if entry.hasOrder {
        let i = min(max(entry.stepIndex, 0), 3)
        VStack(spacing: 8) {
          ZStack {
            Circle().fill(Color.blue).overlay(Circle().stroke(Color.white, lineWidth: 2))
            Group {
              if let img = stepIconImages[i] {
                Image(uiImage: img)
                  .renderingMode(.template)
                  .resizable()
                  .scaledToFit()
                  .frame(width: 26, height: 26)
              } else {
                Image(systemName: "circle")
                  .font(.system(size: 22))
              }
            }
            .foregroundColor(.white)
          }
          .frame(width: 56, height: 56)
          Text(stepLabels[i].uppercased())
            .font(.system(size: 12, weight: .bold))
            .foregroundColor(.white)
            .lineLimit(1)
            .minimumScaleFactor(0.7)
          Text(entry.restaurantName)
            .font(.system(size: 9, weight: .semibold))
            .foregroundColor(.white.opacity(0.85))
            .lineLimit(1)
        }
        .padding()
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .widgetBackground(orange)
      } else {
        EmptyOrderView().widgetBackground(orange)
      }
    }
  }

  // .systemMedium — exactamente el diseño de siempre, naranja de borde a
  // borde, sin la tarjeta del repartidor (no cabe).
  private var mediumBody: some View {
    cardContent.widgetBackground(orange)
  }

  // .systemLarge — la tarjeta naranja ya no ocupa todo el widget (su propio
  // RoundedRectangle, no el fondo del contenedor); abajo, si ya hay
  // repartidor confirmado, la tarjeta blanca flota sobre el fondo oscuro.
  private var largeBody: some View {
    VStack(spacing: 10) {
      cardContent.background(RoundedRectangle(cornerRadius: 28).fill(orange))
      riderCard
      Spacer(minLength: 0)
    }
    .padding(12)
    .widgetBackground(Color.black)
  }

  var body: some View {
    if entry.hasOrder {
      switch family {
      case .systemSmall: AnyView(smallBody)
      case .systemLarge: AnyView(largeBody)
      default: AnyView(mediumBody)
      }
    } else {
      AnyView(EmptyOrderView().widgetBackground(orange))
    }
  }
}

struct GOGOTrackingStepsWidget: Widget {
  let kind: String = "GOGOTrackingStepsWidget"

  var body: some WidgetConfiguration {
    StaticConfiguration(kind: kind, provider: GOGOTrackingStepsProvider()) { entry in
      GOGOTrackingStepsWidgetEntryView(entry: entry)
    }
    .configurationDisplayName("GOGO Food (pasos)")
    .description("Muestra el pedido activo con los 4 pasos: Recibido, Preparando, En camino, Entregado. En chico solo el paso actual; en grande también muestra al repartidor una vez confirmado.")
    .supportedFamilies([.systemSmall, .systemMedium, .systemLarge])
  }
}

@main
struct GOGOWidgetBundle: WidgetBundle {
  var body: some Widget {
    GOGOTrackingWidget()
    GOGOTrackingStepsWidget()
  }
}
